/*****************************************************************************
 * @enum IMX728_SensorState_e
 * @brief IMX728 Sensor state enumeration
 *
 * This enumeration defines the different operational states of the IMX728
 * sensor, including sleep, standby, streaming, and safe modes.
 ****************************************************************************/
typedef enum {
	IMX728_SENSOR_STATE_INVALID		= -1,
	IMX728_SENSOR_STATE_SLEEP		= 0x02,
	IMX728_SENSOR_STATE_STANDBY		= 0x04,
	IMX728_SENSOR_STATE_STREAMING		= 0x10,
	IMX728_SENSOR_STATE_SAFE		= 0x20,
} IMX728_SensorState_e;

/*****************************************************************************
 * @enum IMX728_RemapMode_e
 * @brief IMX728 Remap mode enumeration
 *
 * This enumeration defines the different remap modes for the IMX728 sensor,
 * including standby, streaming, and sleep modes with various pixel
 * compensation options.
 ****************************************************************************/
typedef enum {
	IMX728_REMAP_MODE_INVALID				= -1,
	IMX728_REMAP_MODE_STANDBY				= 0x00,
	IMX728_REMAP_MODE_STANDBY_PIXEL_SHADING_COMPENSATION	= 0x01,
	IMX728_REMAP_MODE_STANDBY_SPOT_PIXEL_COMPENSATION	= 0x02,
	IMX728_REMAP_MODE_STREAMING				= 0x04,
	IMX728_REMAP_MODE_STREAMING_PIXEL_SHADING_COMPENSATION	= 0x05,
	IMX728_REMAP_MODE_STREAMING_SPOT_PIXEL_COMPENSATION	= 0x06,
	IMX728_REMAP_MODE_SLEEP					= 0x20,
} IMX728_RemapMode_e;

/*****************************************************************************
 * @enum IMX728_RawMode_e
 * @brief IMX728 Raw image mode enumeration
 *
 * This enumeration defines the different raw image modes supported by
 * the IMX728 sensor, including linear, LI, HDR, and LI_HDR modes.
 ****************************************************************************/
typedef enum {
	IMX728_IMG_MODE_LINEAR			= 0x0,
	IMX728_IMG_MODE_LI			= 0x1,
	IMX728_IMG_MODE_HDR			= 0x2,
	IMX728_IMG_MODE_LI_HDR			= 0x3,
} IMX728_RawMode_e;

/*****************************************************************************
 * @enum IMX728_DriveMode_e
 * @brief IMX728 Drive mode enumeration
 *
 * This enumeration defines the different drive modes for the IMX728 sensor,
 * specifying resolution, frame rate, lane configuration, and bit depth
 * combinations for various operational scenarios.
 ****************************************************************************/
typedef enum {
	IMX728_MODE_3856x2176_45_4LANE_RAW10	= 0x01,
	IMX728_MODE_3856x2176_45_4LANE_RAW12	= 0x02,
	IMX728_MODE_3856x2176_45_4LANE_RAW16	= 0x03,
	IMX728_MODE_3856x2176_45_4LANE_RAW20	= 0x04,
	IMX728_MODE_3856x2176_45_4LANE_RAW12_HDR = 0x05,
	IMX728_MODE_3856x2176_40_4LANE_RAW10	= 0x11,
	IMX728_MODE_3856x2176_40_4LANE_RAW12	= 0x12,
	IMX728_MODE_3856x2176_40_4LANE_RAW16	= 0x13,
	IMX728_MODE_3856x2176_40_4LANE_RAW20	= 0x14,
	IMX728_MODE_3856x2176_40_4LANE_RAW12_HDR = 0x16,
} IMX728_DriveMode_e;

/*****************************************************************************
 * @enum IMX728_AEMode
 * @brief IMX728 Auto Exposure mode enumeration
 *
 * This enumeration defines the different auto exposure modes supported
 * by the IMX728 sensor, including automatic, hold, scale, and full
 * manual exposure control modes.
 ****************************************************************************/
typedef enum {
	IMX728_AEMODE_AE_AUTO			= 0,
	IMX728_AEMODE_AE_HOLD			= 1,
	IMX728_AEMODE_SCALE_ME			= 2,
	IMX728_AEMODE_FULL_ME			= 3,
} IMX728_AEMode;

/*****************************************************************************
 * @enum IMX728_AWBMode_e
 * @brief IMX728 Auto White Balance mode enumeration
 *
 * This enumeration defines the different auto white balance modes
 * supported by the IMX728 sensor, including ATW, pull-in, user preset,
 * full manual, and hold modes.
 ****************************************************************************/
typedef enum {
	IMX728_AWBMODE_ATW			= 0,
	IMX728_AWBMODE_ALL_PULL_IN		= 1,
	IMX728_AWBMODE_USER_PRESET		= 2,
	IMX728_AWBMODE_FULL_MWB			= 3,
	IMX728_AWBMODE_HOLD			= 4,
} IMX728_AWBMode_e;

/*****************************************************************************
 * @enum IMX728_FMEShtvalUnit_e
 * @brief IMX728 Frame shutter value unit enumeration
 *
 * This enumeration defines the different units for frame shutter value
 * configuration in the IMX728 sensor, including lines, microseconds,
 * and frames.
 ****************************************************************************/
typedef enum {
	IMX728_FME_SHTVAL_UNIT_LINES		= 1,
	IMX728_FME_SHTVAL_UNIT_MICROSECONDS	= 3,
	IMX728_FME_SHTVAL_UNIT_FRAMES		= 4,
} IMX728_FMEShtvalUnit_e;

/*****************************************************************************
 * @enum IMX728_FMWBAgainUnit_e
 * @brief IMX728 Full manual white balance analog gain unit enumeration
 *
 * This enumeration defines the different units for analog gain configuration
 * in full manual white balance mode, including 0.1dB, 0.3dB, and
 * magnification factor units.
 ****************************************************************************/
typedef enum {
	IMX728_FMWB_AGAIN_UNIT_0_1DB		= 0,
	IMX728_FMWB_AGAIN_UNIT_0_3DB		= 1,
	IMX728_FMWB_AGAIN_UNIT_MAG_FACT		= 2
} IMX728_FMWBAgainUnit_e;

/*****************************************************************************
 * @enum IMX728_FMWBDgainUnit_e
 * @brief IMX728 Full manual white balance digital gain unit enumeration
 *
 * This enumeration defines the different units for digital gain configuration
 * in full manual white balance mode, including 0.1dB and magnification
 * factor units.
 ****************************************************************************/
typedef enum {
	IMX728_FMWB_DGAIN_UNIT_0_1DB		= 0,
	IMX728_FMWB_DGAIN_UNIT_MAG_FACT		= 1
} IMX728_FMWBDgainUnit_e;

typedef struct {
	IsiSensorContext_t	isiCtx;
	IsiSensorMode_t		sensorMode;

	uint32_t		maxFps;
	uint32_t		minFps;
	uint32_t		currFps;

	bool_t			configured;
	bool_t			streaming;
	bool_t			testPattern;

	float32_t		oneLineExpTime;
	uint16_t		maxIntegrationLine;
	uint16_t		minIntegrationLine;
	uint16_t		frameLengthLines;
	uint16_t		curFrameLengthLines;
	IsiGainInfo_t		aGain;
	IsiGainInfo_t		dGain;

	float32_t		aecMinGain;
	float32_t		aecMaxGain;
	float32_t		aecMinIntegrationTime;
	float32_t		aecMaxIntegrationTime;
	float32_t		aecIntegrationTimeIncrement;
	float32_t		aecGainIncrement;

	IsiSensorIntTime_t	aecCurIntTime;
	IsiSensorGain_t		aecCurGain;


	IsiSensorGain_t		curAgain;
	IsiSensorGain_t		curDgain;

	IsiSensorWb_t		sensorWb;
	IsiSensorBlc_t		sensorBlc;


	uint32_t		i2cId;
	uint32_t		sensorDevId;
	osMutex			registerLock;
	bool_t			regAccessEnable;
} IMX728_Context_t;

